    {
        "name": "Feline Norovirus Infection",
        "name_ja": "猫ノロウイルス感染症",
        "symptoms": {"vomiting", "diarrhea", "lethargy", "appetite_loss", "dehydration"},
        "description": "フランシセラ・ツラレンシスによる細菌性人獣共通感染症で、ウサギやげっ歯類の捕食で感染します。",
        "description_ja": "猫ノロウイルスによるウイルス性胃腸炎で、急性の嘔吐と下痢を引き起こします。",
        "urgency": "moderate",
        "recommended_tests": ["fecal_exam", "pcr_test", "physical_exam"],
        "causes": "猫における野兎病の原因: フランシセラ・ツラレンシスによる細菌性人獣共通感染症で、ウサギやげっ歯類の捕食で感染します。",
        "causes_ja": "猫における猫ノロウイルス感染症の原因: 猫ノロウイルスによるウイルス性胃腸炎で、急性の嘔吐と下痢を引き起こします。",
        "pathophysiology": "野兎病は猫における細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "pathophysiology_ja": "猫ノロウイルス感染症は猫におけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "猫における野兎病の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "treatment_ja": "猫における猫ノロウイルス感染症の治療は主に支持療法であり、多くのウイルス感染症には特異的抗ウイルス薬がない。輸液療法により水分補給と電解質補正を行う。解熱鎮痛薬で発熱と不快感を管理する。広域抗菌薬で二次細菌感染を予防・治療する。食欲不振時の補助給餌を含む栄養サポートが不可欠である。免疫賦活剤やインターフェロンが有効な場合がある。感受性個体への伝播防止のため罹患個体を隔離する。",
        "prevention": "野兎病の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prevention_ja": "猫ノロウイルス感染症の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "",
        "prognosis_ja": "猫ノロウイルス感染症の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
